package dev.exodus.teleporter.client;
import dev.exodus.teleporter.menu.ExodusTeleporterMenu;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.entity.player.Inventory;
public final class ExodusTeleporterScreen extends AbstractContainerScreen<ExodusTeleporterMenu>{private static final ResourceLocation TEXTURE=new ResourceLocation("minecraft","textures/gui/container/dispenser.png");public ExodusTeleporterScreen(ExodusTeleporterMenu menu,Inventory inv,Component title){super(menu,inv,title);imageHeight=166;inventoryLabelY=72;}@Override protected void renderBg(GuiGraphics g,float partial,int mx,int my){g.blit(TEXTURE,leftPos,topPos,0,0,imageWidth,imageHeight);}@Override public void render(GuiGraphics g,int mx,int my,float partial){renderBackground(g);super.render(g,mx,my,partial);renderTooltip(g,mx,my);}}
